std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::vector<std::size_t> col_idx(cols_);
    std::iota(col_idx.begin(), col_idx.end(), std::size_t{0});
    std::transform(col_idx.begin(), col_idx.end(), result.begin(),
                   [this](std::size_t c) {
                       return std::accumulate(
                           this->data_.cbegin() + static_cast<std::ptrdiff_t>(c * rows_),
                           this->data_.cbegin() + static_cast<std::ptrdiff_t>((c + 1) * rows_),
                           0.0);
                   });
    return result;
}

std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::vector<std::size_t> col_idx(cols_);
    std::iota(col_idx.begin(), col_idx.end(), std::size_t{0});
